import math

def E(n):
    if 2*n - 1 == 0:
        return None # Should not happen for non-negative integers n
    return 3 * (math.factorial(n + 2) + 1) / (2*n - 1)

test_values = [0, 1, 2, 3, 4, 5]
results = {}
for n in test_values:
    result = E(n)
    is_integer = result == int(result)
    results[n] = (result, is_integer)

print("Results for n = 0 to 5:")
for n, (value, is_int) in results.items():
    print(f"n={n}: E(n) = {value} (Integer: {is_int})")

def check_condition(n):
    if 2 * n - 1 == 0:
        return False # Should not happen for non-negative n
    try:
        numerator = 3 * (((n + 2) * factorial(n + 2)) + 1)
        denominator = 2 * n - 1
        if numerator % denominator == 0:
            return True
        else:
            return False
    except ValueError:
        return False

from math import factorial

test_n = [0, 1, 2, 3, 4, 5, 6, 7]
results = {n: check_condition(n) for n in test_n}
print(results)

